python3 -c "
items = {
'item1_PTStore': {
'core_conclusion':'现有推理运行时KV缓存多困于单机，致跨节点复用需重算，PTStore用CDN思路把热前缀张量分布复制到多节点多卡以降低TTFT。',
'mechanism':'借鉴CDN客户端缓存把可复用KV前缀张量增量存储并复制到各节点，用RDMA并行服务最长公共前缀查询。',
'result':'长文问答上效率比不聚合内存的基线高5到6倍，8k token的TTFT约为vLLM前缀缓存的两倍速。',
'boundary':'仅报告TTFT与端到端时间，未给TPOT或P95及生产硬件规模。',
'project_relevance':'为分布式KV聚合改变存储网络边界提供参照，可评估热前缀复制对跨节点复用的收益。'
},
'item2_HBF': {
'core_conclusion':'AI推理同时受带宽与容量挤压，SK hynix与SanDisk经OCP发布首个开放高带宽闪存HBF标准，填补HBM与SSD之间的新层。',
'mechanism':'用堆叠NAND die提供类HBM高速传输并扩容，经UCIe可接GPU或CPU。',
'result':'规范容量至512GB分8层与16层堆叠，带宽分三档约从0.4到3.0TB每秒。',
'boundary':'仅为公告阶段规范未给耐久时延功耗或量产时间等实测。',
'project_relevance':'UCIe开放标准化利处理器无关部署，但项目须区分公告规范与量产能力再纳入存储分层。'
},
'item3_ThAME': {
'core_conclusion':'MoE推理受专家权重带宽与非确定token路由双重夹击，ThAME用3D FeFET加DRAM多芯粒与层次NoC，在仿真上同时解这两道墙。',
'mechanism':'把专家权重存于片上3D FeFET-NAND并用AMOSA设计的层次NoC缓解非确定路由流量。',
'result':'仿真上相对Stratum等基线最高加速15.7倍能效提升9.8倍达147.5 Tokens每秒每瓦。',
'boundary':'全部为周期级仿真无流片，未给端到端服务P95。',
'project_relevance':'为FeFET近存计算进入AI内存层级提供架构投影，须等流片或预硅验证再判断。'
},
'item4_DNOVA': {
'core_conclusion':'RAG向量检索是主时延瓶颈，既有存内加速仍把重排留给处理器，D-NOVA用双界相似度感知把IVF检索直接做进3D NAND阵列，避免数据搬移。',
'mechanism':'用双界紧相似度感知把向量检索化为对NAND阈值电平的查询相关门限搜索，仅紧凑分数离开阵列。',
'result':'仿真上比CPU基线快41.7倍能效71倍，相对REIS时延降至约四分之一。',
'boundary':'仿真基于QLC NAND无流片，未给端到端RAG时延或耐久影响。',
'project_relevance':'展示NAND阵列可承担AI检索角色，为存内计算改变存储层级边界提供仿真依据。'
},
'item5_Kioxia': {
'core_conclusion':'AI与超大规模数据中心同时要容量带宽与能效，Kioxia与SanDisk第十代332层QLC以CBA架构与4.8 Gb每秒接口同时提升这三项。',
'mechanism':'CBA分晶圆造CMOS与阵列再键合，配Toggle DDR6.0加SCA与PI-LTT降I/O功耗。',
'result':'相对第八代位密度提升至多60%超37 Gb每平方毫米，为首款4.8 Gb每秒QLC闪存。',
'boundary':'产品公告未给耐久时延绝对吞吐或量产时间等实测。',
'project_relevance':'为AI存储层提供容量带宽能效的代际信号，须等耐久与实测再判断层级边界。'
},
'item6_KAP': {
'core_conclusion':'知识选择前端产出的结构化先验被提示序列化压平，致后端密集消费全KV，KAP用运行时访问计划IR把物理KV访问与提示长度解耦。',
'mechanism':'把知识先验编译为运行时访问计划治理物理KV访问，GraphSpec连接GraphRAG与vLLM。',
'result':'128K上下文上KV访问仅占源状态5.5%，解码吞吐相对全上下文提升1.19倍且答案质量保持。',
'boundary':'仅一种实例与长文QA评估，TTFT因计划编译略升且无生产规模数据。',
'project_relevance':'为解耦物理KV消费与提示长度提供可借鉴IR，可评估对推理后端吞吐的增益。'
},
'item7_Deltoris': {
'core_conclusion':'扩散式VLA模型算力重，难满足50到200Hz实时控制，Deltoris用时间感知位级稀疏加推测推理，把差分计算摊销到验证步。',
'mechanism':'利用连续帧98%像素不变只算差分并以位串行执行活跃位，轻量模型预测多动作由重模型验证摊销访存。',
'result':'相对移动GPU最高加速34.2倍相对既有加速器6.1倍，运算量最高降92.9%。',
'boundary':'精度仅称相当且未见物理机器人端到端时延或瓦级功耗实测。',
'project_relevance':'把控制回路时间冗余转为吞吐的机制可借鉴，须等真实部署数据再判断边端价值。'
},
'item8_Hawk': {
'core_conclusion':'LLM生成NPU内核因缺硬件先验在昇腾上成功率极低，且正确内核也慢于GPU约20倍，Hawk用硬件感知知识把成功率大幅拉高。',
'mechanism':'运行时合成可执行知识并用二维检索对齐语法与硬件语义空间，再以编译执行反馈蒸馏剪枝。',
'result':'昇腾内核生成准确率由49.4%升至80.0%，实测最高2.2倍执行加速。',
'boundary':'仅覆盖L1与L2内核，难扩展到高级NPU集群的复杂融合算子。',
'project_relevance':'为昇腾等非CUDA平台补齐内核生成短板提供工具参照，可评估对真实吞吐的提升。'
}
}
for name, fields in items.items():
    total = sum(len(v) for v in fields.values())
    flag = ' OK' if 180 <= total <= 260 else ' OUT'
    flag2 = ''
    for f,v in fields.items():
        lim = {'core_conclusion':75,'mechanism':50,'result':50,'boundary':35,'project_relevance':50}
        if len(v) > lim[f]:
            flag2 += f' {f}={len(v)}>{lim[f]}'
    print(f'{name}: total={total}{flag}{flag2}')
"

